'use client';

import {
  Children,
  isValidElement,
  useState,
  type ReactElement,
  type ReactNode,
} from 'react';

import { cn } from '@/lib/utils';
import { CopyButton } from '@/registry/default/ui-fragments/copy-button';
import {
  CodeSnippet,
  type TCodeSnippetProps,
} from '@/registry/default/ui/code/code-snippet';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/registry/default/ui/tabs';

export type TApiSnippetTabProps = {
  value: string;
  label: ReactNode;
  language: NonNullable<TCodeSnippetProps['language']>;
  code: string;
};

export function ApiSnippetTab(_props: TApiSnippetTabProps) {
  return null;
}

export type TApiSnippetProps = {
  children: ReactNode;
  header?: ReactNode;
  footer?: ReactNode;
  defaultValue?: string;
  value?: string;
  onValueChange?: (value: string) => void;
  clipCodeHeight?: boolean;
  className?: string;
};

const CLIPPED_CODE_HEIGHT = 240;

export function ApiSnippet({
  children,
  header,
  footer,
  defaultValue,
  value,
  onValueChange,
  clipCodeHeight = false,
  className,
}: TApiSnippetProps) {
  const tabs = Children.toArray(children)
    .filter(
      (child): child is ReactElement<TApiSnippetTabProps> =>
        isValidElement(child) && child.type === ApiSnippetTab
    )
    .map((child) => child.props);
  const [internalValue, setInternalValue] = useState(
    defaultValue ?? tabs[0]?.value
  );
  const activeTab =
    tabs.find((t) => t.value === (value ?? internalValue)) ?? tabs[0];

  if (!activeTab) return null;

  const isSingleTab = tabs.length === 1;
  const handleValueChange = (next: string) => {
    if (value === undefined) setInternalValue(next);
    onValueChange?.(next);
  };

  return (
    <div
      className={cn(
        'not-prose w-full overflow-hidden rounded-md border bg-card text-card-foreground',
        className
      )}
    >
      {header && <div className="border-b p-2">{header}</div>}
      <Tabs
        value={activeTab.value}
        onValueChange={handleValueChange}
        className="gap-0"
      >
        <div className="flex items-center border-b bg-muted/40 pr-2">
          <TabsList variant="line" className="px-2 pl-0 -ml-px">
            {tabs.map((t) => (
              <TabsTrigger
                key={t.value}
                value={t.value}
                className={isSingleTab ? 'after:hidden' : undefined}
              >
                {t.label}
              </TabsTrigger>
            ))}
          </TabsList>
          <CopyButton text={activeTab.code} className="ml-auto" />
        </div>
        {tabs.map((t) => (
          <TabsContent
            key={t.value}
            value={t.value}
            className={clipCodeHeight ? 'm-0 overflow-y-auto' : 'm-0'}
            style={
              clipCodeHeight ? { maxHeight: CLIPPED_CODE_HEIGHT } : undefined
            }
          >
            <CodeSnippet
              code={t.code}
              language={t.language}
              bordered={false}
              canCopy={false}
            />
          </TabsContent>
        ))}
      </Tabs>
      {footer && <div className="flex items-center border-t p-2">{footer}</div>}
    </div>
  );
}

export type TStackOperation = {
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE' | 'HEAD' | 'OPTIONS';
  path: string;
  pathParams: string[];
  sdk?: { module: string; method: string };
  summary?: string;
  tags?: string[];
};

export type TStackOperationsIndex = {
  _meta?: { specVersion?: string; specFile?: string };
  operations: Record<string, TStackOperation>;
};

export type TResolvedOperation = {
  method: string;
  baseUrl: string;
  path: string;
  query: [string, unknown][];
  headers: Record<string, string>;
  body?: unknown;
  bodyFile?: string;
  rawArgs?: string;
  pathParams?: Record<string, string>;
  sdk?: { module: string; method: string };
};

export type TResolveOperationInput = {
  params?: Record<string, string>;
  query?: [string, unknown][];
  body?: unknown;
  bodyFile?: string;
  rawArgs?: string;
  baseUrl?: string;
  headers?: Record<string, string>;
};

const MAX_COMPACT_LENGTH = 80;

export function resolvePathParams(
  path: string,
  params?: Record<string, string>
): string {
  if (!params) return path;
  let resolved = path;
  for (const [k, v] of Object.entries(params))
    resolved = resolved.replace(`{${k}}`, v);

  return resolved;
}

export function resolveOperation(
  operation: TStackOperation,
  {
    params,
    query = [],
    body,
    bodyFile,
    rawArgs,
    baseUrl = '$FORMANCE_API_URL',
    headers = {},
  }: TResolveOperationInput = {}
): TResolvedOperation {
  return {
    method: operation.method,
    baseUrl,
    path: resolvePathParams(operation.path, params),
    query,
    headers,
    body,
    bodyFile,
    rawArgs,
    pathParams: params,
    sdk: operation.sdk,
  };
}

function shellSingleQuote(value: string): string {
  return `'${value.replace(/'/g, `'\\''`)}'`;
}

function formatValue(label: string, value: unknown): string {
  if (typeof value !== 'object' || value === null) return `${label}${value}`;
  const compact = `${label}${JSON.stringify(value)}`;
  if (compact.length <= MAX_COMPACT_LENGTH) return compact;

  return `${label}${JSON.stringify(value, null, 2).replace(/\n/g, '\n  ')}`;
}

export function generateCurl(op: TResolvedOperation): string {
  const isGet = op.method === 'GET';
  const queryString = op.query
    .map(
      ([k, v]) =>
        `${encodeURIComponent(k)}=${encodeURIComponent(typeof v === 'object' && v !== null ? JSON.stringify(v) : String(v))}`
    )
    .join('&');
  const url =
    isGet || !queryString
      ? `${op.baseUrl}${op.path}`
      : `${op.baseUrl}${op.path}?${queryString}`;
  const parts = [isGet ? `curl -G "${url}"` : `curl -X ${op.method} "${url}"`];
  if (isGet)
    for (const [k, v] of op.query)
      parts.push(
        `  --data-urlencode ${shellSingleQuote(formatValue(`${k}=`, v))}`
      );
  for (const [k, v] of Object.entries(op.headers))
    parts.push(`  -H "${k}: ${v}"`);
  if (op.bodyFile) {
    parts.push(`  -H "Content-Type: application/json"`);
    parts.push(`  -d @${shellSingleQuote(op.bodyFile)}`);
  } else if (op.body !== undefined) {
    parts.push(`  -H "Content-Type: application/json"`);
    parts.push(`  -d ${shellSingleQuote(formatValue('', op.body))}`);
  }
  if (op.rawArgs) parts.push(`  ${op.rawArgs}`);

  return parts.join(' \\\n');
}

export function generateHttpie(op: TResolvedOperation): string {
  const verb = op.method === 'GET' ? '' : `${op.method} `;
  const parts = [`http ${verb}"${op.baseUrl}${op.path}"`];
  for (const [k, v] of op.query)
    parts.push(`  ${shellSingleQuote(formatValue(`${k}==`, v))}`);
  for (const [k, v] of Object.entries(op.headers)) parts.push(`  "${k}:${v}"`);
  if (op.bodyFile) parts.push(`  < ${shellSingleQuote(op.bodyFile)}`);
  else if (op.body !== undefined)
    parts.push(`  --raw ${shellSingleQuote(formatValue('', op.body))}`);
  if (op.rawArgs) parts.push(`  ${op.rawArgs}`);

  return parts.join(' \\\n');
}

export function generateSdk(op: TResolvedOperation): string {
  if (!op.sdk) return '';

  const args: Record<string, unknown> = {
    ...op.pathParams,
    ...Object.fromEntries(op.query),
    ...(op.body && typeof op.body === 'object' && !Array.isArray(op.body)
      ? op.body
      : {}),
  };
  const argsBlock = Object.keys(args).length
    ? JSON.stringify(args, null, 2)
    : '{}';
  const namespace = op.sdk.module.replace(/V(\d+)$/, '.v$1');
  const call = [namespace, op.sdk.method].filter(Boolean).join('.');

  return [
    `import { SDK } from '@formance/formance-sdk';`,
    ``,
    `const sdk = new SDK({ serverURL: ${op.baseUrl.startsWith('$') ? `process.env.${op.baseUrl.slice(1)}` : JSON.stringify(op.baseUrl)} });`,
    ``,
    `const result = await sdk.${call}(${argsBlock});`,
  ].join('\n');
}
